var s={en:`Sensors on trucks report temperatures every minute; operators receive alerts and can change safe set-points. Devices may be disconnected for hours.`,ua:`Датчики у вантажівках щохвилини надсилають температуру; оператори отримують тривоги й можуть безпечно змінювати цільове значення. Зв’язок може зникати на години.`};var t={en:[`Draw devices, edge, authenticated broker, ingestion, time-series store and rules.`,`Model offline buffering, timestamps and deduplication.`,`Add authorized commands, audit, expiry and physical safety checks.`],ua:[`Намалюй пристрої, edge, автентифікований брокер, приймання, time-series БД та правила.`,`Змоделюй офлайн-буфер, час подій і дедуплікацію.`,`Додай авторизовані команди, аудит, строк дії та фізичні запобіжники.`]};var i=[{en:`Device identity is verified before accepting traffic.`,ua:`Особу пристрою перевіряють до приймання трафіку.`},{en:`Commands have authenticated source and acknowledgement state.`,ua:`Команди мають перевірене джерело й підтвердження.`}];var n={scenario:s,tasks:t,checks:i};export{i as checks,n as default,s as scenario,t as tasks};